[Form]
public class TFMMenuItemActionLookup extends FormRun
{
    boolean                 okButtonClicked;
    boolean                 cancelButtonClicked;
    TFMPageLookupContent    lookupContent;
    str                     selectedID;
    TFMPageMenuItemType     selectedType;
    Map						adHocAttributes;

}

public void closeSelect(str _selectString)
{
    if(okButtonClicked)
    {
        super(_selectString);

        if(this.caller_RU() && formHasMethod(this.caller_RU(), formMethodStr(TFMPageConfigurator, CloseLookupForMenuItems)))
        {
            this.caller_RU().CloseLookupForMenuItems(_selectString);
        }


    }
    else if(cancelButtonClicked)
    {
        if(this.caller_RU() && formHasMethod(this.caller_RU(), formMethodStr(TFMPageConfigurator, CloseLookupForMenuItems)))
        {
            // inform the calling page that the lookup closes and it was cancelled.
            this.caller_RU().CloseLookupForMenuItems();
        }
    }
}

public void init()
{

    TFMPagesTmpLookup   localTmp;
    MapEnumerator       pages = TFMPagesProvider::getAllPages().getPages().getEnumerator();
    TFMPage             page;
    TFMPage             currentPage;
    TFMPagesTmpLookup   localCommandsTmp;
    Object caller;
    TFMPageConfigurationAttributeAttribute	configAttr;
    TFMPageActionAttribute                  actionAttr;
    SysDictMethod			                DM;
    SetEnumerator                           methodSet;

    adHocAttributes	= new Map(Types::String, Types::Class);
    okButtonClicked = false;
    cancelButtonClicked = false;

    super();
    localTmp.setTmp();
    localTmp.clear();

    caller = this.caller_RU();
    currentPage = caller.getCurrentPage();

    while (pages.moveNext())
    {
        page = pages.currentValue();

        if(page.parmId() == currentPage.parmId())
        {
            continue;
        }

        localTmp.PageId = page.parmId();
        localTmp.Icon = page.parmIcon();
        localTmp.Title = TFMListVisualization::getMenuTitle(page.parmTitle());
        localTmp.PageType = enum2Str(TFMPageMenuItemTypes::OpenAction);

        if(this.isNotAlreadyAMenuItemOnThePage(currentPage.parmId(), localTmp.PageId))
        {
            localTmp.insert();
        }
    }
    PagesTmp.setTmpData(localTmp);
    lookupContent = new TFMPageLookupContent(this.FormGroupControl_Page, PagesTmp, false);

    localCommandsTmp.setTmp();
    methodSet = TFMFormLookupHelper::parmMethodsOnClass(classIdGet(currentPage.getConfiguration())).getEnumerator();
    while (methodSet.moveNext())
    {
        DM = new SysDictMethod(UtilElementType::ClassInstanceMethod,classIdGet(currentPage.getConfiguration()),methodSet.current());

        configAttr = DM.getAttribute(classStr(TFMPageConfigurationAttributeAttribute));


        if (!configAttr || configAttr.parmExcludeFromXmlOutput()) // if the enabled is present it is threated as a menu item.
        {
            continue;
        }

        select firstonly localCommandsTmp where localCommandsTmp.PageId == configAttr.parmXPath();
        if(localCommandsTmp.PageID)
        {
            // if it is already in the list no need to add it again.
            continue;
        }

        actionAttr = DM.getAttribute(classStr(TFMPageActionAttribute));
        if(actionAttr && (actionAttr.parmMenuItemType() != TFMPageMenuItemTypes::OfflinePageMenuItem || (actionAttr.parmMenuItemType() == TFMPageMenuItemTypes::OfflinePageMenuItem && currentPage.getConfiguration().isOfflineEnabled())))
        {
            localCommandsTmp.PageId = configAttr.parmXPath();
            localCommandsTmp.Title = TFMListVisualization::getMenuTitle(configAttr.parmDefaultValue() ? configAttr.parmDefaultValue() : methodSet.current());
            localCommandsTmp.PageType = enum2Str(actionAttr.parmMenuItemType());
            if(this.isNotAlreadyAMenuItemOnThePage(currentPage.parmId(), localCommandsTmp.PageId))
            {
                localCommandsTmp.insert();
            }
        }
    }

    // Add default menu items for pages
    localCommandsTmp.PageID = TFMConstants::MenuItemTypeBarcode();
    localCommandsTmp.Title = TFMListVisualization::getMenuTitle(TFMConstants::MenuItemTypeBarcode());
    localCommandsTmp.PageType = enum2Str(TFMPageMenuItemTypes::PageMenuItem);
    if(this.isNotAlreadyAMenuItemOnThePage(currentPage.parmId(), localCommandsTmp.PageId))
    {
        localCommandsTmp.insert();
    }

    localCommandsTmp.PageID = TFMConstants::MenuItemShowImage();
    localCommandsTmp.Title = TFMListVisualization::getMenuTitle(TFMConstants::MenuItemShowImage());
    localCommandsTmp.PageType = enum2Str(TFMPageMenuItemTypes::PageMenuItem);

    if(this.isNotAlreadyAMenuItemOnThePage(currentPage.parmId(), localCommandsTmp.PageId))
    {
        localCommandsTmp.insert();
    }

    CommandsTmp.setTmpData(localCommandsTmp);

    this.lookupDocumentTypesForAdhocRegistrations(currentPage.parmId());
}

public void addAdhocItemToMap(MethodName _methodName, TFMDocumentHandler _handler)
{

    TFMPageAdhocMenuItemsAdditionalProperties	additionalProps;
    SysDictMethod								sdm;
    TFMDocumenttypeAttribute					docTypeAttr;

    sdm = new SysDictMethod(UtilElementType::ClassInstanceMethod,classIdGet(_handler), _methodName);
    docTypeAttr = sdm.getAttribute(ClassStr(TFMDocumenttypeAttribute));
    if(docTypeAttr)
    {
        additionalProps = new TFMPageAdhocMenuItemsAdditionalProperties();
        additionalProps.parmDocumentType(docTypeAttr.parmDocumentType());
        additionalProps.parmContentType(docTypeAttr.parmContentType());
        additionalProps.parmRefreshOnSuccess(true);
    }
    adHocAttributes.insert(_methodName,additionalProps);
}

public void lookupDocumentTypesForAdhocRegistrations(str _currentPageId)
{
    TFMPagesTmpLookup   localAdhocActionsTmp;
    TFMDocumentHandler					docHand;

    Map									attributes		= TFMAttributeHandler::getAttributesFromClasses(classStr(TFMPageLineAdhocRequestAttribute));
    MapEnumerator						attrEnum = attributes.getEnumerator();

    TFMPageLineAdhocRequestAttribute	valAttr;

    localAdhocActionsTmp.setTmp();

    while (attrEnum.moveNext())
    {
        valAttr = attrEnum.currentValue();
        docHand = SysExtensionAppClassFactory::getClassFromSysAttribute(classStr(TFMDocumentHandler),valAttr);

        localAdhocActionsTmp.PageID = valAttr.parmMethodName();
        localAdhocActionsTmp.Title = TFMListVisualization::getMenuTitle(valAttr.parmTitle());
        localAdhocActionsTmp.PageType = enum2Str(TFMPageMenuItemTypes::AdhocAction);
        localAdhocActionsTmp.Icon = valAttr.parmIcon();
        if(this.isNotAlreadyAMenuItemOnThePage(_currentPageId, localAdhocActionsTmp.PageId))
        {
            localAdhocActionsTmp.insert();
            element.addAdhocItemToMap(valAttr.parmMethodName(), docHand);
        }
    }
    AdhocActionsTmp.setTmpData(localAdhocActionsTmp);
}

/// <summary>
///
/// </summary>
/// <returns></returns>
public int active()
{
    int ret;
    TFMPageMenuItemTypes menuItemType;

    ret = super();
    if(PagesTmp)
    {
        if(PagesTmp.Icon)
        {
            lookupContent.setIcon(PagesTmp.Icon);
        }
        selectedID = PagesTmp.PageID;
        if(PagesTmp.PageType)
        {
            selectedType = str2Enum(menuItemType, PagesTmp.PageType);
        }
        else
        {
            selectedType = TFMPageMenuItemTypes::OpenAction;
        }
    }

    return ret;
}

/// <summary>
///
/// </summary>
/// <returns></returns>
public int active()
{
    int ret;
    TFMPageMenuItemTypes menuItemType;

    ret = super();

    if(CommandsTmp)
    {
        selectedID = CommandsTmp.PageID;
        if(selectedID == 'showImage')
        {
            selectedType = TFMPageMenuItemTypes::showImage;
        }
        else

        {
            selectedType = str2Enum(menuItemType, CommandsTmp.PageType);
        }
    }
    return ret;
}

/// <summary>
///
/// </summary>
/// <returns></returns>
public int active()
{
    int ret;
    TFMPageMenuItemTypes menuItemType;

    ret = super();

    if(AdhocActionsTmp)
    {
        selectedID = AdhocActionsTmp.PageID;
        if(selectedID == enum2Str(TFMPageMenuItemTypes::showImage))
        {
            selectedType = TFMPageMenuItemTypes::showImage;
        }
        else
        {
            selectedType = str2Enum(menuItemType, AdhocActionsTmp.PageType);
        }
    }
    return ret;
}

/// <summary>
///
/// </summary>
/// <param name = "_FromTab"></param>
/// <param name = "_ToTab"></param>
public void tabChanged(int _FromTab, int _ToTab)
{
    super(_FromTab, _ToTab);
    this.getActivePage().dataSourceObject().active();
}

void clicked()
{
    TFMPageMenuItems record;
    TFMPageAdhocMenuItemsAdditionalProperties	additionalProps;
    MapEnumerator								mEnum;
    TFMPage										page;
    okButtonClicked = true;
    record = element.args().record() as TFMPageMenuItems;
    record.MenuItemType = selectedType;
    if (selectedType == TFMPageMenuItemTypes::AdhocAction)
    {
        record.Icon = AdhocActionsTmp.Icon;
        record.Title = AdhocActionsTmp.Title;
        if (adHocAttributes.exists(selectedID))
        {
            additionalProps = adHocAttributes.lookup(selectedID);
            mEnum = additionalProps.getparameters().getEnumerator();
            while(mEnum.moveNext())
            {
                page = TFMPagesProvider::getAllPages().getPage(record.pageId);
                TFMPageConfigParms::CreateOrUpdateParameter(record.pageId , classId2Name(classIdGet(page.getConfiguration())), selectedID + mEnum.currentKey(), conPeek(mEnum.currentValue(),1));
            }

        }
    }

    element.closeSelect(selectedID);
    super();
}

/// <summary>
///
/// </summary>
public void clicked()
{
    cancelButtonClicked = true;
    element.closeSelect('');
    super();

}
